/* Service worker for the Soil Health PWA.
 *
 * Hand-written rather than generated by next-pwa: that package has no Next 16 support,
 * and the caching rules here are specific enough that explicit control is clearer than
 * configuring a generator.
 *
 * Strategy per asset class — rural connectivity is the reason this is a PWA at all:
 *
 *   app shell / static      cache-first, precached on install  -> opens with no network
 *   navigations             network-first, fall back to shell  -> always renders something
 *   GET /api/... reads      stale-while-revalidate             -> last diagnosis stays readable
 *   POST /api/... writes    never cached; queued when offline  -> replayed on reconnect
 *   POST /api/analyze       never cached, never queued         -> must run server-side, live
 */

/* Bump VERSION on any change to the shell, to sw.js itself, or to server-rendered markup.
 * The activate handler deletes every cache whose key does not match, so a bump is what
 * actually evicts stale entries — without one, `cacheFirst` below pins the old copy
 * indefinitely and a returning visitor runs old assets against new HTML, which surfaces as
 * a React hydration mismatch rather than as anything that looks cache-related.
 */
const VERSION = 'v5';
const SHELL_CACHE = `shell-${VERSION}`;
const DATA_CACHE = `data-${VERSION}`;

// Minimal shell: enough to render the app offline. Route chunks are added on first visit.
const SHELL_ASSETS = [
  '/',
  '/manifest.webmanifest',
  '/favicon.ico',
  '/icons/favicon-16.png',
  '/icons/favicon-32.png',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
];

// Reads worth keeping for offline viewing.
const CACHEABLE_READ = /\/api\/(farms|fields|soil-records|images|analysis-results|models|crop-suitability|trends)/;

// Writes that can safely be replayed later. /analyze is excluded: it is not idempotent
// in a useful way and the farmer needs its response immediately, not eventually.
const QUEUEABLE_WRITE = /\/api\/(soil-records|images|farms|fields)$/;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      // addAll rejects the whole batch if any single request fails, which would abort
      // the install. Add individually and tolerate misses.
      .then((cache) => Promise.allSettled(SHELL_ASSETS.map((a) => cache.add(a))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((k) => k !== SHELL_CACHE && k !== DATA_CACHE)
            .map((k) => caches.delete(k)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Never touch cross-origin requests.
  if (url.origin !== self.location.origin) return;

  if (request.method !== 'GET') {
    if (QUEUEABLE_WRITE.test(url.pathname)) {
      event.respondWith(writeWithQueue(request));
    }
    return; // everything else, including /api/analyze, goes straight to the network
  }

  if (request.mode === 'navigate') {
    event.respondWith(networkFirstNavigation(request));
    return;
  }

  if (CACHEABLE_READ.test(url.pathname)) {
    event.respondWith(staleWhileRevalidate(request));
    return;
  }

  event.respondWith(cacheFirst(request));
});

/* Immutable build output. Next fingerprints these filenames, so the content behind a given
 * URL never changes and cache-first is always safe. Anything NOT matching this is treated as
 * mutable and revalidated, so a changed asset at a stable URL cannot be served stale.
 */
const IMMUTABLE_ASSET = /^\/_next\/static\/(?!chunks\/_|chunks\/src)/;

async function cacheFirst(request) {
  const path = new URL(request.url).pathname;
  const cached = await caches.match(request);

  // Fingerprinted output: trust the cache outright.
  if (cached && IMMUTABLE_ASSET.test(path)) return cached;

  // Everything else may have changed at a stable URL — most importantly dev chunks, whose
  // names are NOT content-hashed. Revalidate, and fall back to the cached copy only when
  // the network is unavailable.
  if (cached) {
    try {
      const fresh = await fetch(request);
      if (fresh.ok && fresh.type === 'basic') {
        const cache = await caches.open(SHELL_CACHE);
        cache.put(request, fresh.clone());
      }
      return fresh;
    } catch {
      return cached;
    }
  }
  try {
    const response = await fetch(request);
    if (response.ok && response.type === 'basic') {
      const cache = await caches.open(SHELL_CACHE);
      cache.put(request, response.clone());
    }
    return response;
  } catch {
    return new Response('', { status: 504, statusText: 'Offline' });
  }
}

async function networkFirstNavigation(request) {
  try {
    return await fetch(request);
  } catch {
    /* Offline: serve the cached shell so the app still boots and can show its own offline
     * banner, rather than the browser's error page.
     *
     * LANGUAGE CAVEAT: next-i18next renders the shell server-side from the language cookie, so
     * this cached copy is frozen in whichever language was current when it was cached. Offline
     * there is no server to re-render it. `LocaleSync` (mounted in AppChrome) re-applies the
     * stored preference on the client right after boot, so the farmer sees their language even
     * though the first paint may briefly be the cached one. */
    return (await caches.match('/')) ?? new Response('', { status: 504 });
  }
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(DATA_CACHE);
  const cached = await cache.match(request);

  const network = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => null);

  // Return the cached copy immediately when there is one; the fetch refreshes it in the
  // background for the next visit.
  if (cached) {
    network.catch(() => {});
    return cached;
  }

  const fresh = await network;
  return fresh ?? new Response(JSON.stringify({ detail: 'Offline and not cached.' }), {
    status: 503,
    headers: { 'Content-Type': 'application/json' },
  });
}

/* ------------------------------------------------------------------ write queue --- */
/* Failed writes are stored in IndexedDB and replayed when the device reconnects. This is
 * the whole point of the PWA for a farmer standing in a field with one bar of signal. */

const DB_NAME = 'soil-health-queue';
const STORE = 'requests';

function openDb() {
  return new Promise((resolve, reject) => {
    const open = indexedDB.open(DB_NAME, 1);
    open.onupgradeneeded = () => {
      open.result.createObjectStore(STORE, { keyPath: 'id', autoIncrement: true });
    };
    open.onsuccess = () => resolve(open.result);
    open.onerror = () => reject(open.error);
  });
}

/* Drop cached reads that a successful write has just invalidated.
 *
 * THE BUG THIS FIXES
 * `staleWhileRevalidate` returns the cached copy immediately and refreshes in the background.
 * That is right for reading a diagnosis offline, but wrong straight after a write: creating a
 * field then reloading served the PREVIOUS (empty) `/farms/{id}/fields` response, so a newly
 * created plot did not appear until the background refresh landed on some later visit. The
 * write returned 201 and the UI still said "No plots yet".
 *
 * Clearing the data cache on any successful write is blunt but correct — the cache exists for
 * offline reading, not for saving a round-trip on a screen the user just changed.
 */
async function invalidateDataCache() {
  try {
    await caches.delete(DATA_CACHE);
  } catch {
    /* cache API unavailable — the next fetch simply goes to the network */
  }
}

async function writeWithQueue(request) {
  try {
    const response = await fetch(request.clone());
    if (response.ok) await invalidateDataCache();
    return response;
  } catch {
    // Body must be read before storing; a Request body is single-use.
    const body = await request.clone().arrayBuffer();
    const db = await openDb();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(STORE, 'readwrite');
      tx.objectStore(STORE).add({
        url: request.url,
        method: request.method,
        headers: [...request.headers],
        body,
        queuedAt: Date.now(),
      });
      tx.oncomplete = resolve;
      tx.onerror = () => reject(tx.error);
    });

    if ('sync' in self.registration) {
      try {
        await self.registration.sync.register('flush-queue');
      } catch {
        /* Background Sync unavailable — the queue flushes on the next 'online' event. */
      }
    }

    return new Response(
      JSON.stringify({
        queued: true,
        detail: 'Saved on this device. It will be sent when you are back online.',
      }),
      { status: 202, headers: { 'Content-Type': 'application/json' } },
    );
  }
}

async function flushQueue() {
  const db = await openDb();
  const items = await new Promise((resolve, reject) => {
    const tx = db.transaction(STORE, 'readonly');
    const req = tx.objectStore(STORE).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });

  if (items.length === 0) return;

  let sent = 0;
  for (const item of items) {
    try {
      const response = await fetch(item.url, {
        method: item.method,
        headers: item.headers,
        body: item.body,
      });
      // Drop the item on success, and also on a 4xx: a validation error will never
      // succeed on replay, so retrying forever would wedge the queue. A 401 counts —
      // the token stored with the request expired while it waited, and no amount of
      // retrying revives it.
      if (response.ok || (response.status >= 400 && response.status < 500)) {
        await deleteItem(db, item.id);
        if (response.ok) sent += 1;
      }
    } catch {
      break; // still offline — stop and keep the remaining items for the next attempt
    }
  }

  if (sent > 0) {
    const clients = await self.clients.matchAll();
    clients.forEach((c) => c.postMessage({ type: 'queue-flushed', sent }));
  }
}

function deleteItem(db, id) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE, 'readwrite');
    tx.objectStore(STORE).delete(id);
    tx.oncomplete = resolve;
    tx.onerror = () => reject(tx.error);
  });
}

self.addEventListener('sync', (event) => {
  if (event.tag === 'flush-queue') event.waitUntil(flushQueue());
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'flush-queue') flushQueue();
});
